import{_ as t}from"./chunks/ec2ac0f5e01065296ba1.CPgyq7Tl.js";import{_ as o,o as a,c as n,a6 as r}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"The Simple 3 Point Online Business Model","description":"","frontmatter":{"title":"The Simple 3 Point Online Business Model","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-simple-3-point-online-business-model.md","filePath":"en/letters/the-simple-3-point-online-business-model.md"}'),i={name:"en/letters/the-simple-3-point-online-business-model.md"};function s(l,e,u,h,d,p){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="the-simple-3-point-online-business-model" tabindex="-1">The Simple 3 Point Online Business Model <a class="header-anchor" href="#the-simple-3-point-online-business-model" aria-label="Permalink to &quot;The Simple 3 Point Online Business Model&quot;">​</a></h1><p>Dan Koe · 2022-03-01 · <a href="https://thedankoe.com/letters/the-simple-3-point-online-business-model/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-simple-3-point-online-business-model">返回中文译文</a></p><p>In a world of over-complication, I am on a mission to simplify the complex. Business is one of the most simple things out there, but most of us never touched a business book during our childhood. We think that building a business is reserved for people with startup capital, a top 1% skillset, and/or a huge following + paid ads.</p><p>Let’s take a step back and see what you really need to hit the $5K, $10K, and even $50K per month mark.</p><p>The 3 point online business model is as follows:</p><ol><li>Social media account</li><li>Email List</li><li>Offer</li></ol><p>They all interconnect, so stick to the end of the letter to understand the big picture of it all.</p><h2 id="point-1-social-media-account" tabindex="-1"><strong>Point 1) Social Media Account</strong> <a class="header-anchor" href="#point-1-social-media-account" aria-label="Permalink to &quot;**Point 1) Social Media Account**&quot;">​</a></h2><p>Your social media account is your new resume.</p><p>Your content displays your expertise, interests, and personality.</p><p>And with paid ads becoming less viable, your social accounts are a free organic traffic source that you can send to your offers (what you are selling).</p><p>Most people see social media growth as daunting. It is. But there are proven methods for growth and monetization. It would be silly to start growing an account if you have no idea what you are doing… that’s why it’s so daunting in the first place.</p><p><em>Side note: you don’t need a lot of followers to make 6 figures+. Yes, they help, A LOT, but you don’t need them. You can grow to build leverage while pulling in a decent income.</em></p><p>All of this is like learning to play a game (because that’s what it is). At first, a game is boring because you don’t know how to play. But you play anyway, learn the rules, the fundamentals, how to win, and eventually it becomes fun. You want to play the game more because it starts to become an art as opposed to a science.</p><p>The same goes for social media. The rules are the platforms terms of service. The fundamentals are the growth mechanisms (how you get maximum exposure and convert those readers to followers). The mechanics reflect in your content. In the case of Twitter, the mechanics lie in your ability to write punchy content relevant to your interests.</p><p>Since your social media account serves as the face of your brand, how do you get started?</p><h3 id="create-a-content-pyramid" tabindex="-1"><strong>Create A Content Pyramid</strong> <a class="header-anchor" href="#create-a-content-pyramid" aria-label="Permalink to &quot;**Create A Content Pyramid**&quot;">​</a></h3><p>Your content pyramid holds all of the topics that you want to talk about, usually branching down from 2-3 main pillars. Mine are self-improvement, online business, and a spiritual take on performance.</p><p>Yours can be anything. If somebody is talking about it online and has grown an audience, there is no reason you can’t do the same. Another good metric: if you could talk to a friend for hours about a specific topic, why not talk to people online about it?</p><p><img src="'+t+'" alt="The Content Pyramid"></p><p>The Content Pyramid</p><h3 id="craft-a-followable-profile" tabindex="-1"><strong>Craft A Followable Profile</strong> <a class="header-anchor" href="#craft-a-followable-profile" aria-label="Permalink to &quot;**Craft A Followable Profile**&quot;">​</a></h3><p>Don’t overthink this step. Everybody else already is. Have a good looking profile photo, a compelling bio that answers the question, “What’s in it for me?” (the reader), and have a link that leads to your offers to show readers that you are a creator — not a consumer.</p><p>A question to consistently ask yourself, does my account look like it should have 100,000 followers? No? Change something.</p><h3 id="understand-the-current-growth-meta" tabindex="-1"><strong>Understand The Current Growth Meta</strong> <a class="header-anchor" href="#understand-the-current-growth-meta" aria-label="Permalink to &quot;**Understand The Current Growth Meta**&quot;">​</a></h3><p>Again, this is a game. You need to understand what content results in the most growth for beginners because that is when it is the hardest to grow.</p><p>Think about it, popular YouTubers did not post travel vlogs to get to where they are now. They played the game long enough to where they can now do whatever they want. At the beginning, they posted “how-to” videos and catered to the algorithm. Something that is popular right now are the “I Tried X For 30 Days.”</p><p>On Twitter, the current meta is punchy Tweets and Medium blog-style threads. Join communities, groups, and other places online that discuss what type of content is doing best, or just pay attention to what accounts are doing to grow.</p><h3 id="consistency" tabindex="-1"><strong>Consistency</strong> <a class="header-anchor" href="#consistency" aria-label="Permalink to &quot;**Consistency**&quot;">​</a></h3><p>At the end of the day, you don’t have to pay attention to any of this. You SHOULD, but if you simply stuck it out and corrected your mistakes for a year, you’d have a 5 figure following.</p><p>Your social media account will be your way of selling your offers, making million dollar connections, and building leverage for the future of your brand. If you start a service business, build cashflow, and have a large audience — you can now start ANY business you want relating to your interests and make it a success. I plan on starting a coffee brand soon just because I f*cking love coffee.</p><p><a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">If you want my legacy Twitter growth course, a step-by-step social media growth roadmap, and 154+ other online business strategies, check out the private community (MMHQ) here.</a></p><h3 id="email-list" tabindex="-1"><strong>Email List</strong> <a class="header-anchor" href="#email-list" aria-label="Permalink to &quot;**Email List**&quot;">​</a></h3><p>The unfortunate truth is that you do not own your social media account. It also may not be the best place to sell ALL THE TIME. With that said, you should start building your email list from the start. You don’t NEED to email people or have a set schedule, but it would be silly not to start gathering emails. It will come in handy just in case you get canceled. You own your list.</p><p>Once you have the time, start writing a weekly newsletter. These newsletters can be turned into sequences, threads, blog posts, or YouTube videos down the road when you are ready to go down that avenue. For now, focus on developing your ideas and testing what resonates with your audience.</p><p>When you have your offer (product or service ready) you can create email sequences to sell them on autopilot. Then, all you have to do is post content to your social account, plug your newsletter, and make sales without doing any of the work.</p><p>Start with a welcome sequence. Have a welcome email that tells everyone what you talk about, your vision for your brand, and what they can expect in future emails. Then, have 2-3 emails that go over your story or the big problem you are aiming to solve. After that, you can put subscribers into a sales sequence for your offer. The emails should raise their awareness level of the problem you solve, show them the solution, and sprinkle in a bit of urgency so they buy.</p><p>With a social media account and email list alone, you can pull in a hefty income over time. This is an ultra-lean one-person business model. 3-4 hours a day (possibly less) of work — IF you have a solid offer / offer stack.</p><p><a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">If you want access to the step-by-step email marketing roadmap, you can get it inside MMHQ.</a></p><h3 id="your-offer" tabindex="-1"><strong>Your Offer</strong> <a class="header-anchor" href="#your-offer" aria-label="Permalink to &quot;**Your Offer**&quot;">​</a></h3><p>For beginners, your offer is your product or service. It is what you SELL. You have to sell something if you want to make money, that’s a given (that not many people understand). Stop trying to make passive income when you don’t have active income.</p><p>“Dan, what do I sell?”</p><p>What are you interested in? What do you have experience in? What do you have results in? Have you solved a problem in your life through trial and error? Can you help people navigate that trial and error? <em>What are the people that you follow selling and could you sell the same thing? (Buyers buy again, don’t reinvent the wheel).</em></p><p>I tried freelancing for 3 years, finally made it work, then wrote a book on how I did it. I knew that freelancing books were already selling, so I created my own and sold it to the people that trusted me over the competition (your personal brand eliminates competition).</p><p>I loved planners, got results from them, created my own, and sold it (some of you know it as the Power Planner).</p><p>After freelancing, I created a marketing consulting offer and targeted creators. Why? Because I saw other people selling it, knew how to take creators from point A to point B, and sold it for $8,000. This sounds absurd to some because you haven’t started yet. Again, like playing a game, you have no idea what happens later in the game because you haven’t taken the first step.</p><p>Now, there are a few things to take into account here:</p><ul><li>People don’t care about everything inside your product or service, they care about the SPECIFIC result that you can get them (and everything that helps them get that result)</li><li><a href="https://youtu.be/kC1IvnzM_-A?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">You can create a compelling guarantee even if you don’t have results.</a> This is what will make you the most money.</li><li>You must make the journey from point A (problem) to point B (problem solved) as simple and straightforward as possible. The easier you can make it for the buyer to implement it into their life, the better. Systems above all.</li><li>Stop trying to solve every problem. Focus on one burning, biological problem. Test different angles and double down until you see your desired sales.</li></ul><p>At the end of the day, you either have a traffic problem or an offer problem. JK Molina said it best:</p><blockquote><p>&quot;It&#39;s always a traffic or offer problem&quot; concept changed my life\\</p><p>Not enough money? Improve your offer or get more traffic\\</p><p>Not enough girls? Get better (offer) or meet more girls (traffic)\\</p><p>There&#39;s always a solution. And it&#39;s one of those two.</p><p>— JK MOLINA (@OneJKMolina) <a href="https://twitter.com/OneJKMolina/status/1492150948831109120?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">February 11, 2022</a></p></blockquote><p>If you can’t make money, that’s why. Anything other than that is a consistency and iteration problem.</p><p><a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">If you want my Godfather Offer Framework and Advanced Marketing Roadmap…. again, it’s inside MMHQ lol</a> (everything is inside MMHQ).</p><p>Ending it here. Have an amazing weekend my friends, make it count.</p><p><em><strong>Dan Koe</strong></em></p>',54)])])}const f=o(i,[["render",s]]);export{y as __pageData,f as default};
